protected boolean validateDiscPct()
{
    boolean ret = next validateDiscPct();

    // Clear error message when the discount line is creating. Need to open the Edit price attribute form.
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        !ret && 
        !this.PriceAttributeGroupCombinationRecId)
    {
        infolog.clear(infolog.line() - 1);
        return true;
    }

    return ret;
}
